  };

  const handleEditClick = (dish) => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setIsEditing(true);
    setEditId(dish.id);
    setNewDish({ name: dish.name, price: dish.price, description: dish.description, category: dish.category, image: null });
