  };

  const handleDeleteDish = async (dish) => {
    const result = await Swal.fire({
      title: 'Supprimer ce plat ?',
      text: `Voulez-vous vraiment retirer "${dish.name}" de votre Menu ?`, 
      icon: 'warning',
