      cancelButtonColor: '#000000',
      reverseButtons: true
    });
    if (result.isConfirmed) {
      try {
        await axios.delete(`http://127.0.0.1:8000/api/dishes/${dish.id}/`);
        setAllDishes(prevDishes => prevDishes.filter(d => d.id !== dish.id));
