            <input type="number" placeholder="Prix (DH)" className="border-2 p-4 rounded-xl border-gray-50 bg-gray-50/30" onChange={(e) => setNewDish({...newDish, price: e.target.value})} required value={newDish.price}/>
            <select className="border-2 p-4 rounded-xl bg-white" onChange={(e) => setNewDish({...newDish, category: e.target.value})} required value={newDish.category}>
